const user = { name: "Anna", address: { city: "Krakow" } };

const {
  name: userName,              // zmiana nazwy: name -> userName
  age: userAge = 30,           // wartosc domyslna: age nie istnieje -> 30
  address: { city }            // zagniezdzenie: wyciagniecie city z address
} = user;

console.log(userName); // "Anna"
console.log(userAge);  // 30
console.log(city);     // "Krakow"

const user = { id: 1, name: "Anna", email: "anna@example.com" };

const { id, ...rest } = user;
console.log(id);   // 1
console.log(rest); // { name: 'Anna', email: 'anna@example.com' }

function displayUser({ name, address: { city } = {} }) {
  return `${name} z ${city}`;
}

const user = { name: "Anna Nowak", address: { city: "Krakow" } };
console.log(displayUser(user)); // "Anna Nowak z Krakow"

function pokazMiasto({ address: { city } }) {
  return city;
}

